package com.truckload.controller;
import android.app.*;
import android.content.*;
import android.content.pm.*;
import android.net.Uri;
import android.os.*;
import android.provider.Settings;
import android.widget.*;
import org.json.JSONObject;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.*;
import java.util.concurrent.*;

public final class AppUpdates {
 public static final String DEFAULT_REPOSITORY="heindpl1/Truck-Load-android-app";
 private static final int INSTALL_PERMISSION=62;
 private static final long MAX_APK=30L*1024*1024;
 private final Activity activity;private final Handler main=new Handler(Looper.getMainLooper());
 private final ExecutorService worker=Executors.newSingleThreadExecutor();private Future<?> task;private ProgressDialog progress;private AlertDialog settings;private boolean closed=false,waitingPermission=false;private volatile int generation=0;
 public AppUpdates(Activity a){activity=a;}
 private boolean alive(){return !closed&&!activity.isFinishing()&&!activity.isDestroyed();}
 public void show(){if(!alive())return;if(task!=null&&!task.isDone()){Toast.makeText(activity,"An update check is already running.",Toast.LENGTH_SHORT).show();return;}LinearLayout body=new LinearLayout(activity);body.setOrientation(1);int pad=(int)(20*activity.getResources().getDisplayMetrics().density);body.setPadding(pad,pad,pad,pad);TextView help=new TextView(activity);help.setText("Installed version: "+versionName()+"\n\nCheck GitHub Releases for a newer version. Updates keep your settings and require Android approval. Internet is used only when you check or download an update.\n\nGitHub repository");body.addView(help);EditText repo=new EditText(activity);repo.setSingleLine(true);repo.setHint("owner/repository");repo.setContentDescription("GitHub update repository");repo.setText(activity.getSharedPreferences("updates",0).getString("repository",DEFAULT_REPOSITORY));body.addView(repo);ScrollView scroll=new ScrollView(activity);scroll.addView(body);settings=new AlertDialog.Builder(activity).setTitle("App updates").setView(scroll).setNegativeButton("Close",null).setPositiveButton("Check for updates",null).create();settings.setOnShowListener(d->settings.getButton(-1).setOnClickListener(v->{String r;try{r=UpdatePolicy.repository(repo.getText().toString());}catch(IllegalArgumentException e){repo.setError(e.getMessage());return;}activity.getSharedPreferences("updates",0).edit().putString("repository",r).apply();settings.dismiss();check(r);}));settings.show();}
 private long code(PackageInfo p){return Build.VERSION.SDK_INT>=28?p.getLongVersionCode():p.versionCode;}
 private PackageInfo installed()throws PackageManager.NameNotFoundException{return activity.getPackageManager().getPackageInfo(activity.getPackageName(),flags());}
 private int flags(){return Build.VERSION.SDK_INT>=28?PackageManager.GET_SIGNING_CERTIFICATES:PackageManager.GET_SIGNATURES;}
 private String versionName(){try{return installed().versionName;}catch(Exception e){return "Unknown";}}
 private void message(String title,String text){if(alive())new AlertDialog.Builder(activity).setTitle(title).setMessage(text).setPositiveButton("OK",null).show();}
 private void busy(String title){progress=new ProgressDialog(activity);progress.setTitle(title);progress.setMessage("Please wait…");progress.setCancelable(true);progress.setOnCancelListener(d->{generation++;if(task!=null)task.cancel(true);});progress.show();}
 private void done(){if(progress!=null){progress.dismiss();progress=null;}}
 private interface Job{void run(int request)throws Exception;}
 private void run(String title,Job job){int request=++generation;busy(title);task=worker.submit(()->{try{job.run(request);}catch(Exception e){if(!Thread.currentThread().isInterrupted())main.post(()->{if(alive()&&request==generation){done();message("Update unavailable",e.getMessage()==null?"Please try again when you have internet access.":e.getMessage());}});}});}
 private HttpURLConnection open(String url)throws IOException {for(int i=0;i<6;i++){try{UpdatePolicy.https(url);}catch(IllegalArgumentException e){throw new IOException(e.getMessage());}HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(15000);c.setReadTimeout(15000);c.setRequestProperty("User-Agent","Truckload-Android");c.setRequestProperty("Accept-Encoding","identity");int status=c.getResponseCode();if(status>=300&&status<400){String location=c.getHeaderField("Location");c.disconnect();if(location==null)throw new IOException("The update server returned an invalid redirect.");url=new URL(new URL(url),location).toString();continue;}if(status!=200){c.disconnect();throw new IOException(status==404?"No update release found. The repository must be public and its latest published release must contain truckload-update.json.":"Update server returned HTTP "+status+". Try again later.");}return c;}throw new IOException("The update server redirected too many times.");}
 private byte[] readSmall(String url)throws Exception {HttpURLConnection c=open(url);try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1){if(Thread.currentThread().isInterrupted())throw new InterruptedException();if(out.size()+n>65536)throw new IOException("Update information is too large.");out.write(b,0,n);}return out.toByteArray();}finally{c.disconnect();}}
 private static final class Release {long version,size;String name,url,hash,notes;}
 private void check(String repo){run("Checking for updates",request->{JSONObject j=new JSONObject(new String(readSmall(UpdatePolicy.manifestUrl(repo)),StandardCharsets.UTF_8));Release r=new Release();r.version=j.getLong("versionCode");r.name=j.getString("versionName");r.url=j.getString("apkUrl");r.hash=j.getString("sha256");r.size=j.getLong("sizeBytes");r.notes=j.optString("notes","");UpdatePolicy.https(r.url);if(r.size<1||r.size>MAX_APK||!r.hash.matches("[a-fA-F0-9]{64}")||r.name.length()>80||r.notes.length()>4000)throw new IOException("The release contains invalid update information.");boolean newer=r.version>code(installed());if(Thread.currentThread().isInterrupted())return;main.post(()->{if(!alive()||request!=generation)return;done();if(!newer){message("You're up to date","Truckload "+versionName()+" is installed.");return;}new AlertDialog.Builder(activity).setTitle("Truckload "+r.name+" is available").setMessage(r.notes+"\n\nDownload size: "+Math.max(1,(r.size+1023)/1024)+" KB\nYour settings will be kept.").setNegativeButton("Later",null).setPositiveButton("Download update",(d,w)->download(r)).show();});});}
 private Set<String> signers(PackageInfo info)throws IOException {android.content.pm.Signature[] signatures=Build.VERSION.SDK_INT>=28?(info.signingInfo==null?null:info.signingInfo.getApkContentsSigners()):info.signatures;if(signatures==null||signatures.length==0)throw new IOException("The APK has no readable signing certificate.");Set<String> s=new HashSet<>();for(android.content.pm.Signature sig:signatures)s.add(sig.toCharsString());return s;}
 private void verifyApk(File file,long version)throws Exception {PackageInfo candidate=activity.getPackageManager().getPackageArchiveInfo(file.getAbsolutePath(),flags());PackageInfo current=installed();if(candidate==null||!activity.getPackageName().equals(candidate.packageName))throw new IOException("This download is not a Truckload app update.");if(code(candidate)!=version||code(candidate)<=code(current))throw new IOException("The downloaded APK has an unexpected or older version.");if(candidate.applicationInfo!=null&&candidate.applicationInfo.minSdkVersion>Build.VERSION.SDK_INT)throw new IOException("This update requires a newer Android version.");if(!signers(current).equals(signers(candidate)))throw new IOException("Update blocked: the APK was not signed with your Truckload signing key.");}
 private void download(Release r){run("Downloading Truckload "+r.name,request->{File target=UpdateProvider.file(activity);File dir=target.getParentFile();if(!dir.isDirectory()&&!dir.mkdirs())throw new IOException("Could not prepare the update folder.");File partial=new File(dir,"download.part");boolean complete=false;HttpURLConnection c=open(r.url);try {long declared=c.getContentLengthLong();if(declared>0&&declared!=r.size)throw new IOException("The download size does not match the release.");MessageDigest hash=MessageDigest.getInstance("SHA-256");long total=0;try(InputStream in=c.getInputStream();FileOutputStream out=new FileOutputStream(partial)){byte[] b=new byte[16384];int n;while((n=in.read(b))!=-1){if(Thread.currentThread().isInterrupted())throw new InterruptedException();total+=n;if(total>r.size||total>MAX_APK)throw new IOException("The update download is larger than expected.");out.write(b,0,n);hash.update(b,0,n);}out.getFD().sync();}if(total!=r.size||!UpdatePolicy.hashMatches(r.hash,hash.digest()))throw new IOException("The update failed its integrity check. Please download it again.");verifyApk(partial,r.version);if(Thread.currentThread().isInterrupted())throw new InterruptedException();if(target.exists()&&!target.delete())throw new IOException("Could not replace the previous update download.");if(!partial.renameTo(target))throw new IOException("Could not finish preparing the update.");complete=true;main.post(()->{if(alive()&&request==generation){done();install();}});}finally {c.disconnect();if(!complete)partial.delete();}});}
 private void install(){if(!UpdateProvider.file(activity).isFile()){message("Download missing","Check for updates and download it again.");return;}if(!activity.getPackageManager().canRequestPackageInstalls()){waitingPermission=true;new AlertDialog.Builder(activity).setTitle("Allow app updates").setMessage("Android needs your permission for Truckload to open its downloaded update. Turn on Allow from this source, then return here.").setNegativeButton("Later",(d,w)->waitingPermission=false).setPositiveButton("Open settings",(d,w)->{try{activity.startActivityForResult(new Intent(Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,Uri.parse("package:"+activity.getPackageName())),INSTALL_PERMISSION);}catch(ActivityNotFoundException e){waitingPermission=false;message("Open Android settings","Allow Truckload under Install unknown apps, then check for updates again.");}}).show();return;}waitingPermission=false;Uri uri=Uri.parse("content://"+activity.getPackageName()+".updates/update.apk");Intent intent=new Intent(Intent.ACTION_VIEW).setDataAndType(uri,"application/vnd.android.package-archive").addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);intent.setClipData(ClipData.newRawUri("Truckload update",uri));try{activity.startActivity(intent);}catch(ActivityNotFoundException e){message("Installer unavailable","Android could not open its package installer.");}}
 public boolean activityResult(int request){if(request!=INSTALL_PERMISSION)return false;if(waitingPermission&&activity.getPackageManager().canRequestPackageInstalls())install();else waitingPermission=false;return true;}
 public void close(){closed=true;generation++;if(task!=null)task.cancel(true);worker.shutdownNow();main.removeCallbacksAndMessages(null);done();if(settings!=null)settings.dismiss();}
}


